package com.bank.container;

import java.math.BigDecimal;
import java.util.logging.Logger;

// Finds the widest sustained balance band for National Bank of India charts.
public class ContainerAnalyzer {
    private static final Logger log = Logger.getLogger(ContainerAnalyzer.class.getName());

    // Max container area over monthly balances. O(n), O(1).
    public BigDecimal maxContainerArea(BigDecimal[] heights) {
        if (heights == null || heights.length < 2) {
            return BigDecimal.ZERO;                    // no container possible
        }
        int left = 0;
        int right = heights.length - 1;
        BigDecimal best = BigDecimal.ZERO;
        while (left < right) {
            BigDecimal limiting = heights[left].min(heights[right]); // shorter wall
            BigDecimal width = BigDecimal.valueOf(right - left);     // months apart
            BigDecimal area = limiting.multiply(width);
            if (area.compareTo(best) > 0) {
                best = area;                           // bigger tank found
            }
            // Move the SHORTER side inward (only chance to improve).
            if (heights[left].compareTo(heights[right]) < 0) {
                left++;
            } else {
                right--;
            }
        }
        final BigDecimal result = best;
        log.info(() -> "Max container area = " + result);
        return best;
    }
}
