package com.bank.container;

import java.math.BigDecimal;
import java.util.logging.ConsoleHandler;
import java.util.logging.Logger;

// Runnable demo: widest sustained balance band for Rajesh.
public class ContainerDemo {
    private static final Logger log = Logger.getLogger(ContainerDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler handler = new ConsoleHandler();
        handler.setFormatter(new BankLogFormatter());
        root.addHandler(handler);
    }

    private static BigDecimal bd(String s) { return new BigDecimal(s); }

    public static void main(String[] args) {
        ContainerAnalyzer analyzer = new ContainerAnalyzer();

        // Rajesh (SAV2001) monthly closing balances (in thousands) as bar heights.
        BigDecimal[] balances = { bd("1"), bd("8"), bd("6"), bd("2"), bd("5"), bd("4"), bd("8"), bd("3"), bd("7") };
        BigDecimal area = analyzer.maxContainerArea(balances);
        log.info(() -> "Widest balance band area for Rajesh = " + area);
    }
}
